<script>
export default {
  name: 'FieldOfficerApp',
  props: {
    externalTasks: {
      type: Array,
      default: () => [],
    },
    sharedShelters: {
      type: Array,
      default: () => [],
    },
  },
  watch: {
    sharedShelters: {
      immediate: true,
      handler(list) {
        if (list.length && !this.localShelters.length) {
          this.localShelters = list.map(s => ({ ...s }))
        }
      },
    },
    externalTasks: {
      immediate: true,
      handler(newList) {
        newList.forEach(task => {
          if (!this.tasks.find(t => t.id === task.id)) {
            this.tasks.unshift(task)
          }
        })
      },
    },
    currentStep() {
      this.$nextTick(() => window.scrollTo({ top: 0, behavior: 'instant' }))
    },
    activeTaskTab() {
      this.$nextTick(() => window.scrollTo({ top: 0, behavior: 'instant' }))
    },
  },
  data() {
    const now = new Date()
    return {
      currentStep: 'tasks',
      activeTaskTab: 'new',
      selectedTask: null,
      fieldUrgency: 1,
      peopleCount: 0,
      contactName: '',
      contactPhone: '',
      checkinTime: '',
      closeTime: '',
      otherNeedText: '',
      evidenceImage: null,
      lightboxImage: null,
      showTaskModal: false,
      previewTask: null,
      completionNote: '',
      selectedOutcome: 'resolved',

      taskTabs: [
        { key: 'new', label: 'รับเรื่อง' },
        { key: 'assigned', label: 'กำลังดำเนินการ' },
        { key: 'done', label: 'เสร็จสิ้น' },
      ],

      workflowSteps: [
        { key: 'detail', label: 'ข้อมูลเหตุ' },
        { key: 'checkin', label: 'เช็คอิน' },
        { key: 'complete', label: 'ปิดเคส' },
      ],

      needs: [
        { key: 'food', label: 'อาหาร', checked: false },
        { key: 'oxygen', label: 'ออกซิเจน', checked: false },
        { key: 'clothes', label: 'เสื้อผ้า', checked: false },
        { key: 'other', label: 'อื่นๆ', checked: false },
      ],

      outcomes: [
        { key: 'resolved', icon: 'bi-check-circle-fill', label: 'แก้ไขสำเร็จ' },
        { key: 'transferred', icon: 'bi-truck-front-fill', label: 'ส่งต่อโรงพยาบาล' },
        { key: 'evacuated', icon: 'bi-bus-front-fill', label: 'อพยพแล้ว' },
        { key: 'pending', icon: 'bi-hourglass-split', label: 'รอหน่วยสนับสนุน' },
      ],

      tasks: [],
      localShelters: [],

      todayStr: now.toLocaleDateString('th-TH', {
        weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
      }),
    }
  },
  computed: {
    stepIndex() {
      const keys = this.workflowSteps.map(s => s.key)
      return keys.indexOf(this.currentStep)
    },
    outcomeLabel() {
      const o = this.outcomes.find(o => o.key === this.selectedOutcome)
      return o ? o.label : ''
    },
    outcomeIcon() {
      const o = this.outcomes.find(o => o.key === this.selectedOutcome)
      return o ? o.icon : ''
    },
    newAlertCount() {
      return this.tasks.filter(t => t.status === 'new').length
    },
  },
  methods: {
    openTaskModal(task) {
      this.previewTask = task
      this.showTaskModal = true
    },
    tasksByTab(tab) {
      const map = { new: 'new', assigned: 'assigned', done: 'done' }
      return this.tasks.filter(t => t.status === map[tab])
    },
    urgencyLabel(u) {
      return { low: 'ปกติ', mid: 'ด่วน', high: 'ด่วนมาก' }[u] || u
    },
    taskUrgencyDisplay(task) {
      if (task.priority) {
        return { p1: { cls: 'p1', label: 'P1 · ด่วนมาก' }, p2: { cls: 'p2', label: 'P2 · ด่วน' }, p3: { cls: 'p3', label: 'P3 · ปานกลาง' }, p4: { cls: 'p4', label: 'P4 · ปกติ' } }[task.priority] || { cls: 'p4', label: 'P4 · ปกติ' }
      }
      return { high: { cls: 'p2', label: 'P2 · ด่วน' }, mid: { cls: 'p3', label: 'P3 · ปานกลาง' }, low: { cls: 'p4', label: 'P4 · ปกติ' } }[task.urgency] || { cls: 'p4', label: 'P4 · ปกติ' }
    },
    acceptTask(task) {
      task.status = 'assigned'
      this.activeTaskTab = 'assigned'
    },
    continueTask(task) {
      this.selectedTask = task
      const urgencyMap = { low: 0, mid: 1, high: 2 }
      this.fieldUrgency = urgencyMap[task.urgency] ?? 1
      this.peopleCount = task.peopleCount || 0
      this.contactName = task.contactName || ''
      this.contactPhone = task.contactPhone || ''
      this.needs.forEach(n => { n.checked = false })
      this.otherNeedText = ''
      this.currentStep = 'detail'
    },
    startCheckin() {
      const now = new Date()
      this.checkinTime = now.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit' })
      this.currentStep = 'checkin'
    },
    doCheckin() {
      this.currentStep = 'complete'
    },
    triggerEvidenceUpload() {
      this.$refs.evidenceInput.click()
    },
    handleEvidence(e) {
      const file = e.target.files[0]
      if (!file) return
      const reader = new FileReader()
      reader.onload = ev => { this.evidenceImage = ev.target.result }
      reader.readAsDataURL(file)
    },
    submitCase() {
      const now = new Date()
      this.closeTime = now.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit' })
      if (this.selectedTask) {
        this.selectedTask.status = 'done'
        this.selectedTask.outcome = this.selectedOutcome
        this.selectedTask.completionNote = this.completionNote
        this.selectedTask.evidenceImage = this.evidenceImage
        this.selectedTask.checkinTime = this.checkinTime
        this.selectedTask.closeTime = this.closeTime
        this.selectedTask.fieldUrgency = ['low', 'mid', 'high'][this.fieldUrgency]
        this.selectedTask.otherNeedText = this.otherNeedText
      }
      this.currentStep = 'success'
    },
    backToTasks() {
      this.currentStep = 'tasks'
      this.activeTaskTab = 'done'
      this.evidenceImage = null
      this.completionNote = ''
      this.needs.forEach(n => n.checked = false)
      this.otherNeedText = ''
    },
    toggleShelterStatus(s) {
      s.available = !s.available
      this.$emit('shelters-updated', this.localShelters.map(s => ({ ...s })))
    },
  },
}
</script>

