/* ── Incident Image ── */
.img-count-badge {
  margin-left: 8px;
  background: #f0f2f8;
  color: #555859;
  font-size: 11px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
}

.incident-img-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.incident-thumb {
  position: relative;
  border-radius: 10px;
  overflow: hidden;
  aspect-ratio: 4/3;
  cursor: pointer;
  background: #f0f2f8;
}

.incident-thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.25s;
}

.incident-thumb:hover .incident-thumb-img {
  transform: scale(1.05);
}

.incident-thumb-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  opacity: 0;
  transition: opacity 0.2s;
}

.incident-thumb:hover .incident-thumb-overlay {
  opacity: 1;
}

.incident-img-area {
  background: #f7f7f7;
  border-radius: 10px;
  height: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.incident-img-placeholder {
  color: #bbb;
  font-size: 14px;
}

/* ── Task Preview Modal ── */
.tmodal-overlay {
  position: fixed;
  inset: 0;
  z-index: 500;
  background: rgba(0, 0, 0, 0.52);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.tmodal-panel {
  background: #fff;
  border-radius: 16px;
  width: 100%;
  max-width: 580px;
  max-height: 85vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 8px 48px rgba(0, 0, 0, 0.28);
  overflow: hidden;
}

@media (max-width: 640px) {
  .tmodal-overlay {
    align-items: flex-end;
    padding: 0;
  }

  .tmodal-panel {
    border-radius: 20px 20px 0 0;
    max-width: 100%;
    max-height: 88vh;
    box-shadow: 0 -8px 40px rgba(0, 0, 0, 0.25);
  }
}

.tmodal-hd {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 18px 12px;
  border-bottom: 1px solid #f0f2f8;
  flex-shrink: 0;
}

.tmodal-hd-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.tmodal-close {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  border: 1.5px solid #e0e4ef;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  color: #888;
  cursor: pointer;
  transition: all 0.15s;
}

.tmodal-close:hover {
  border-color: #ef4444;
  color: #ef4444;
}

.tmodal-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.tmodal-info {
  background: #f8f9fc;
  border-radius: 12px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tmodal-img-sect {}

.tmodal-img-head {
  font-size: 13px;
  font-weight: 700;
  color: #555859;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.tmodal-img-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.tmodal-thumb {
  position: relative;
  aspect-ratio: 4/3;
  border-radius: 10px;
  overflow: hidden;
  cursor: pointer;
  background: #f0f2f8;
}

.tmodal-thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.2s;
  display: block;
}

.tmodal-thumb:hover .tmodal-thumb-img {
  transform: scale(1.05);
}

.tmodal-thumb-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.32);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: #fff;
  opacity: 0;
  transition: opacity 0.2s;
}

.tmodal-thumb:hover .tmodal-thumb-overlay {
  opacity: 1;
}

.tmodal-no-img {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 28px;
  color: #bbb;
  font-size: 13px;
  background: #f8f9fc;
  border-radius: 12px;
}

.tmodal-no-img i {
  font-size: 28px;
}

.tmodal-ft {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 12px 18px;
  border-top: 1px solid #f0f2f8;
  flex-shrink: 0;
}

.tmodal-btn-close {
  padding: 9px 18px;
  border-radius: 8px;
  border: 1.5px solid #e0e4ef;
  background: #fff;
  font-family: 'Kanit', 'Inter', sans-serif;
  font-size: 14px;
  font-weight: 600;
  color: #555;
  cursor: pointer;
}

.tmodal-btn-close:hover {
  border-color: #aaa;
  color: #222;
}

.tmodal-phone-link {
  color: #2563eb;
  font-weight: 700;
  text-decoration: none;
}

.tmodal-phone-link:hover {
  text-decoration: underline;
}

.tmodal-needs-row {
  align-items: flex-start;
}

.tmodal-needs-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tmodal-need-chip {
  background: #fdf6d8;
  border: 1.5px solid #f8d247;
  color: #555859;
  font-size: 12px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 999px;
}

.tmodal-fade-enter-active {
  animation: tmodal-in 0.25s cubic-bezier(0.34, 1.2, 0.64, 1);
}

.tmodal-fade-leave-active {
  animation: tmodal-out 0.18s ease-in;
}

@keyframes tmodal-in {
  from {
    opacity: 0;
    transform: scale(0.94) translateY(8px);
  }

  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes tmodal-out {
  from {
    opacity: 1;
    transform: scale(1);
  }

  to {
    opacity: 0;
    transform: scale(0.94);
  }
}

@media (max-width: 640px) {
  .tmodal-fade-enter-active {
    animation: tmodal-in-mobile 0.28s cubic-bezier(0.34, 1.3, 0.64, 1);
  }

  .tmodal-fade-leave-active {
    animation: tmodal-out-mobile 0.18s ease-in;
  }

  @keyframes tmodal-in-mobile {
    from { transform: translateY(100%); }
    to { transform: translateY(0); }
  }

  @keyframes tmodal-out-mobile {
    from { transform: translateY(0); opacity: 1; }
    to { transform: translateY(100%); opacity: 0; }
  }
}

/* ── Lightbox ── */
.lightbox {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.88);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.lightbox-img {
  max-width: 100%;
  max-height: 90vh;
  border-radius: 12px;
  object-fit: contain;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.6);
}

.lightbox-close {
  position: absolute;
  top: 16px;
  right: 20px;
  background: rgba(255, 255, 255, 0.15);
  border: none;
  border-radius: 50%;
  width: 36px;
  height: 36px;
  color: #fff;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s;
}

.lightbox-close:hover {
  background: rgba(255, 255, 255, 0.28);
}

.fade-enter-active {
  animation: fade-in 0.2s ease;
}

.fade-leave-active {
  animation: fade-in 0.15s ease reverse;
}

@keyframes fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

/* ── Urgency Slider ── */
.urgency-slider-wrap {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.urgency-slider {
  width: 100%;
  accent-color: #f8d247;
  cursor: pointer;
}

.urgency-labels {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  color: #aaa;
}

.urg-active {
  color: #f8d247;
  font-weight: 700;
}

/* ── Needs ── */
.needs-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.need-check {
  display: flex;
  align-items: center;
  gap: 0;
  cursor: pointer;
}

.need-check input {
  display: none;
}

.need-box {
  flex: 1;
  border: 2px solid #e0e4ef;
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 13px;
  font-weight: 600;
  color: #666;
  text-align: center;
  transition: all 0.15s;
  cursor: pointer;
}

.need-box.checked {
  border-color: #f8d247;
  background: #fdf6d8;
  color: #555859;
}

.other-need-wrap {
  margin-top: 8px;
}

.other-need-input {
  width: 100%;
  border: 2px solid #f8d247;
  border-radius: 8px;
  padding: 9px 12px;
  font-size: 13px;
  font-family: inherit;
  outline: none;
  box-sizing: border-box;
  transition: border-color 0.15s;
}

.other-need-input:focus {
  border-color: #e6b800;
}

/* ── People Counter ── */
.people-counter {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
}

.counter-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: #f7f7f7;
  border: 2px solid #e0e4ef;
  font-size: 20px;
  font-weight: 700;
  color: #555859;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s;
}

.counter-btn:hover {
  background: #f8d247;
  border-color: #f8d247;
}

.counter-num {
  font-size: 28px;
  font-weight: 800;
  color: #555859;
  min-width: 48px;
  text-align: center;
}

/* ── Contact ── */
.contact-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.contact-row:last-child {
  margin-bottom: 0;
}

.contact-label {
  width: 36px;
  font-size: 13px;
  color: #888;
  flex-shrink: 0;
}

.contact-input {
  flex: 1;
  border: 1.5px solid #e0e4ef;
  border-radius: 8px;
  padding: 8px 12px;
  font-family: 'Kanit', 'Inter', sans-serif;
  font-size: 14px;
  color: #555859;
  outline: none;
  transition: border-color 0.2s;
}

.contact-input:focus {
  border-color: #f8d247;
}

/* ── Check-in ── */
.checkin-status-card {
  background: #fff;
  border-radius: 14px;
  padding: 24px 18px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.07);
  text-align: center;
}

.checkin-pulse {
  position: relative;
  width: 64px;
  height: 64px;
  margin: 0 auto 14px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pulse-ring {
  position: absolute;
  inset: 0;
  border: 3px solid #f8d247;
  border-radius: 50%;
  animation: pulse 1.5s ease-out infinite;
}

@keyframes pulse {
  0% {
    transform: scale(0.9);
    opacity: 1;
  }

  100% {
    transform: scale(1.5);
    opacity: 0;
  }
}

.pulse-dot {
  font-size: 28px;
  position: relative;
  z-index: 1;
}

.checkin-status-text {
  font-size: 16px;
  font-weight: 700;
  color: #555859;
  margin-bottom: 4px;
}

.checkin-coords {
  font-size: 12px;
  color: #888;
}

.status-badge {
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.status-badge.active {
  background: #dcfce7;
  color: #16a34a;
}

/* ── Complete ── */
.checkin-done-banner {
  background: #dcfce7;
  border: 1.5px solid #86efac;
  border-radius: 10px;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  font-weight: 600;
  color: #166534;
}

.done-icon {
  font-size: 18px;
}

.outcome-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.outcome-radio {
  cursor: pointer;
}

.outcome-radio input {
  display: none;
}

.outcome-box {
  display: block;
  border: 2px solid #e0e4ef;
  border-radius: 8px;
  padding: 10px 8px;
  font-size: 13px;
  font-weight: 600;
  text-align: center;
  color: #666;
  transition: all 0.15s;
  cursor: pointer;
}

.outcome-box.selected {
  border-color: #22c55e;
  background: #dcfce7;
  color: #166534;
}

.completion-note {
  width: 100%;
  border: 1.5px solid #e0e4ef;
  border-radius: 8px;
  padding: 10px 12px;
  font-family: 'Kanit', 'Inter', sans-serif;
  font-size: 14px;
  color: #555859;
  resize: none;
  outline: none;
  transition: border-color 0.2s;
}

.completion-note:focus {
  border-color: #22c55e;
}

.evidence-upload {
  background: #f7f7f7;
  border: 2px dashed #d0d5e0;
  border-radius: 12px;
  min-height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s;
}

.evidence-upload:hover {
  border-color: #f8d247;
  background: #fdf6d8;
}

.evidence-placeholder {
  text-align: center;
}

.evidence-plus {
  font-size: 40px;
  color: #bbb;
  line-height: 1;
}

.evidence-hint {
  font-size: 14px;
  color: #aaa;
  margin-top: 6px;
  font-weight: 600;
}

.evidence-preview {
  width: 100%;
  height: 200px;
  object-fit: cover;
  border-radius: 10px;
}

.upload-change {
  text-align: center;
  color: #888;
  font-size: 13px;
  margin-top: 8px;
  cursor: pointer;
  text-decoration: underline;
}

/* ── Success ── */
.page-success {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.success-content {
  background: #fff;
  border-radius: 20px;
  padding: 40px 28px;
  text-align: center;
  max-width: 420px;
  width: 100%;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.1);
}

.success-icon-wrap {
  position: relative;
  width: 80px;
  height: 80px;
  margin: 0 auto 20px;
}

.success-ring {
  position: absolute;
  inset: 0;
  border: 4px solid #22c55e;
  border-radius: 50%;
  animation: success-ring 0.5s ease-out;
}

@keyframes success-ring {
  from {
    transform: scale(0);
    opacity: 0;
  }

  to {
    transform: scale(1);
    opacity: 1;
  }
}

.success-check {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36px;
  color: #22c55e;
  font-weight: 800;
}

.success-title {
  font-size: 26px;
  font-weight: 800;
  color: #555859;
  margin-bottom: 8px;
}

.success-sub {
  font-size: 15px;
  color: #666;
  margin-bottom: 24px;
}

.success-summary {
  background: #f7f7f7;
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 24px;
  text-align: left;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  padding: 6px 0;
  border-bottom: 1px solid #e8eaf0;
  font-size: 14px;
}

.summary-row:last-child {
  border-bottom: none;
}

.summary-label {
  color: #888;
}

.summary-val {
  font-weight: 700;
  color: #555859;
}

/* ── Buttons ── */
.btn-primary-full {
  background: #555859;
  color: #f8d247;
  border: none;
  border-radius: 12px;
  padding: 14px;
  font-family: 'Kanit', 'Inter', sans-serif;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  width: 100%;
  transition: background 0.2s, transform 0.1s;
}

.btn-primary-full:hover {
  background: #2d2d4e;
  transform: translateY(-1px);
}

.btn-success {
  background: #16a34a;
  color: #fff;
}

.btn-success:hover {
  background: #15803d;
}

/* ── Tasks Header Right ── */
.tasks-header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}

.btn-shelter-nav {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 12px;
  background: rgba(248,210,71,0.15);
  border: 1px solid rgba(248,210,71,0.35);
  border-radius: 8px;
  color: #f8d247;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s;
}

.btn-shelter-nav:hover { background: rgba(248,210,71,0.25); }

/* ── Shelter Management ── */
.page-shelters { flex: 1; }

.btn-add-shelter {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 7px 14px;
  background: #f8d247;
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 700;
  color: #555859;
  cursor: pointer;
  font-family: inherit;
}

.shelter-stat-row {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
}

.shelter-stat {
  flex: 1;
  background: #fff;
  border: 1px solid #e8e8e8;
  border-radius: 12px;
  padding: 14px;
  text-align: center;
}

.shelter-stat-num {
  font-size: 26px;
  font-weight: 800;
  color: #555859;
  line-height: 1;
  margin-bottom: 4px;
}

.shelter-stat-num.available { color: #22c55e; }
.shelter-stat-num.full      { color: #ef4444; }

.shelter-stat-label {
  font-size: 12px;
  color: #888;
}

.shelter-manage-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.shelter-manage-card {
  background: #fff;
  border: 1px solid #e8e8e8;
  border-radius: 14px;
  padding: 14px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.shelter-manage-icon {
  width: 44px;
  height: 44px;
  background: #f3f4f6;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  color: #555859;
  flex-shrink: 0;
}

.shelter-manage-body { flex: 1; min-width: 0; }

.shelter-manage-name {
  font-size: 14px;
  font-weight: 700;
  color: #333;
  margin-bottom: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.shelter-manage-meta {
  font-size: 12px;
  color: #888;
  margin-bottom: 6px;
}

.shelter-manage-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.sm-tag {
  font-size: 10px;
  font-weight: 600;
  background: #f0fdf4;
  color: #166534;
  border: 1px solid #bbf7d0;
  padding: 2px 7px;
  border-radius: 999px;
}

.shelter-manage-actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex-shrink: 0;
  align-items: flex-end;
}

.toggle-btn {
  padding: 5px 12px;
  border-radius: 8px;
  border: none;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  min-width: 50px;
}

.toggle-btn.available { background: #f0fdf4; color: #166534; border: 1px solid #bbf7d0; }
.toggle-btn.full      { background: #fef2f2; color: #991b1b; border: 1px solid #fecaca; }

.sm-edit-btn, .sm-del-btn {
  width: 30px;
  height: 30px;
  border-radius: 7px;
  border: 1px solid #e8e8e8;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  cursor: pointer;
  color: #666;
  transition: all 0.15s;
}

.sm-edit-btn:hover { border-color: #f8d247; color: #555859; }
.sm-del-btn:hover  { border-color: #ef4444; color: #ef4444; }

/* ── Shelter Form ── */
.sf-form { display: flex; flex-direction: column; gap: 0; }

.sf-group {
  margin-bottom: 14px;
}

.sf-label {
  display: block;
  font-size: 12px;
  font-weight: 700;
  color: #555;
  margin-bottom: 6px;
}

.sf-req { color: #ef4444; }

.sf-input {
